window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-02bda491f2322b65"]={"versions": [{"id": "FIG-02bda491f2322b65", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architektur- und Ressourcenallokationsdiagramm (logische Netzwerktopologie, Konfigurationsmatrix und zeitliches PDU-Scheduling-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Bandbreitenmanagements (<em>Bandwidth Control</em>) im FlexRay ISO Transport Layer ([<code>FrTp</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp), ISO 10681-2) bei Nutzung eines gemeinsamen PDU-Pools (<em>Shared PDU Pool</em>) über Flow-Control-Parameter.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Communication Services (zwischen [<code>PduR</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) und [<code>FrIf</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)). Löst Ressourcen- und Buslastkonflikte bei parallelen 1:n- bzw. n:1-Transportverbindungen eines Gateways (<code>GW ECU</code>) zu mehreren Steuergeräten (<code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>) über denselben PDU-Sende-Pool.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Netzwerkknoten (Topology Layer):</strong></li>\n<li><code>GW</code> (<em>Gateway ECU</em>): Zentraler Sender segmentierter FlexRay-Transportnachrichten.</li>\n<li><code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>: Ziel-Steuergeräte (Empfänger) am gemeinsamen FlexRay-Kanal.</li>\n<li><strong>BSW-Konfigurationsentitäten (<code>FrTp</code>-Datenmodell):</strong></li>\n<li><code>Connection_ECU1</code>, <code>Connection_ECU2</code>, <code>Connection_ECU3</code> (<code>FrTpConnection</code>): Konfigurierte logische Punkt-zu-Punkt-Transportverbindungen zwischen <code>GW</code> und den jeweiligen Ziel-ECUs.</li>\n<li><code>PduPool_1</code> (<code>FrTpPduPool</code>): Gemeinsamer Pool vorkonfigurierter FlexRay-Sende-PDUs ([<code>FrIfTxPdu</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)), der von allen drei Verbindungen referenziert wird (<code>PduPoolRef = PduPool_1</code>).</li>\n<li><code>Limited BW</code> (<code>FrTpBandwidthLimitation</code>): Boolescher Verbindungsparameter zur Aktivierung der Ratenbegrenzung:</li>\n<li><code>Connection_ECU1</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU2</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU3</code>: <code>False</code> (keine statische/zusätzliche Bandbreitenbegrenzung)</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>$3:1$-Beziehung: Drei logische <code>FrTpConnection</code>-Instanzen teilen sich einen gemeinsamen physischen <code>FrTpPduPool</code> (<code>PduPool_1</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitbasis (Transmissions-Slots GW1 bis GW4):</strong></li>\n<li>Die Abszisse stellt vier aufeinanderfolgende Sendezeitpunkte bzw. FlexRay-Kommunikationszyklen des Gateways dar (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>, <code>GW4</code>).</li>\n<li>Jeder farbige Block repräsentiert eine aus <code>PduPool_1</code> allozierte PDU (Consecutive Frame, CF), die an die adressierte Ziel-ECU gesendet wird.</li>\n<li><strong>Ablauf & PDU-Zuteilung pro Zyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus GW1:</strong> Maximaler Paralleldurchsatz. Aus <code>PduPool_1</code> werden gleichzeitig drei PDUs bereitgestellt: je eine für <code>ECU 1</code> (rot), <code>ECU 2</code> (blau) und <code>ECU 3</code> (grün).</li>\n<li><strong>Zyklus GW2:</strong> <code>Connection_ECU1</code> pausiert (FlowControl-Beschränkung aktiv). Es werden zwei PDUs versendet: an <code>ECU 2</code> und <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW3:</strong> <code>Connection_ECU2</code> pausiert ebenfalls (Separation-Cycle-Bedingung greift). Es wird nur eine PDU versendet: an <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW4:</strong> Erneut sendet nur <code>Connection_ECU3</code> (<code>Limited BW = False</code>) kontinuierlich in jedem Zyklus (1 PDU an <code>ECU 3</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Steuerungsmechanismus (ISO 10681-2 Flow Control):</strong></li>\n<li>Die Drosselung erfolgt über Empfänger-definierte Flow-Control-Parameter:</li>\n<li><code>SC</code> (<em>Separation Cycle</em>): Definiert die minimale Anzahl von FlexRay-Zyklen zwischen zwei aufeinanderfolgenden CFs.</li>\n<li><code>MNPC</code> (<em>Max Number of PDUs per Cycle</em>): Begrenzt die Frame-Anzahl pro Zyklus.</li>\n<li><code>BS</code> (<em>Block Size</em>): Bestimmt das Quittierungsintervall via Flow Control Frames (FC).</li>\n<li>Bei <code>Limited BW = True</code> wird das Senden gestreckt (Duty-Cycle-Reduktion), wodurch Verbindungen ohne Begrenzung (<code>Connection_ECU3</code>) freiwerdende Slot-Kapazitäten im PDU-Pool monopolisieren können.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>FrTp.epc</code> / ARXML):</strong></li>\n<li>Parameter <code>FrTpBandwidthLimitation</code> steuert, ob die Verbindungs-Zustandsmaschine des <code>FrTp</code> den PDU-Pool-Zugriff drosselt.</li>\n<li>Wenn mehrere Verbindungen auf einen gemeinsamen <code>FrTpPduPool</code> gemappt werden, muss über <code>Limited BW = True</code> sichergestellt werden, dass hochfrequente Bulk-Transfers (z. B. Flashen/UDS-Upload) unlimitierte Echtzeit-/Diagnoseverbindungen nicht aushungern (<em>Starvation Prevention</em>).</li>\n<li><strong>Scheduling in der <code>FrTp_MainFunction()</code>:</strong></li>\n<li>Der interne Zykluszähler für <code>Separation Cycle</code> (<code>SC</code>) wird im Kontext der zyklischen Main-Function dekrementiert.</li>\n<li>Erst wenn der Zähler abgelaufen ist und der <code>FrTpPduPool</code> freie PDU-Ressourcen meldet, ruft <code>FrTp</code> [<code>FrIf_Transmit()</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) auf.</li>\n<li><strong>Hardware-Puffer-Schutz (HW FIFO / Message Buffers):</strong></li>\n<li>Die Begrenzung verhindert RX-Pufferüberläufe ([<code>OVFLW</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)) auf Steuergeräten mit begrenzter Verarbeitungsgeschwindigkeit oder kleinen Empfangs-FIFOs, ohne dass separate, exklusive FlexRay-Slots für jedes Steuergerät reserviert werden müssen.</li>\n</ul>"}, {"id": "FIG-b44ac6e3ddf2438d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architektur- und Ressourcenallokationsdiagramm (logische Netzwerktopologie, Konfigurationsmatrix und zeitliches PDU-Scheduling-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Bandbreitenmanagements (<em>Bandwidth Control</em>) im FlexRay ISO Transport Layer ([<code>FrTp</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp), ISO 10681-2) bei Nutzung eines gemeinsamen PDU-Pools (<em>Shared PDU Pool</em>) über Flow-Control-Parameter.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Communication Services (zwischen [<code>PduR</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) und [<code>FrIf</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)). Löst Ressourcen- und Buslastkonflikte bei parallelen 1:n- bzw. n:1-Transportverbindungen eines Gateways (<code>GW ECU</code>) zu mehreren Steuergeräten (<code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>) über denselben PDU-Sende-Pool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Netzwerkknoten (Topology Layer):</strong></li>\n<li><code>GW</code> (<em>Gateway ECU</em>): Zentraler Sender segmentierter FlexRay-Transportnachrichten.</li>\n<li><code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>: Ziel-Steuergeräte (Empfänger) am gemeinsamen FlexRay-Kanal.</li>\n<li><strong>BSW-Konfigurationsentitäten (<code>FrTp</code>-Datenmodell):</strong></li>\n<li><code>Connection_ECU1</code>, <code>Connection_ECU2</code>, <code>Connection_ECU3</code> (<code>FrTpConnection</code>): Konfigurierte logische Punkt-zu-Punkt-Transportverbindungen zwischen <code>GW</code> und den jeweiligen Ziel-ECUs.</li>\n<li><code>PduPool_1</code> (<code>FrTpPduPool</code>): Gemeinsamer Pool vorkonfigurierter FlexRay-Sende-PDUs ([<code>FrIfTxPdu</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)), der von allen drei Verbindungen referenziert wird (<code>PduPoolRef = PduPool_1</code>).</li>\n<li><code>Limited BW</code> (<code>FrTpBandwidthLimitation</code>): Boolescher Verbindungsparameter zur Aktivierung der Ratenbegrenzung:</li>\n<li><code>Connection_ECU1</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU2</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU3</code>: <code>False</code> (keine statische/zusätzliche Bandbreitenbegrenzung)</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>$3:1$-Beziehung: Drei logische <code>FrTpConnection</code>-Instanzen teilen sich einen gemeinsamen physischen <code>FrTpPduPool</code> (<code>PduPool_1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitbasis (Transmissions-Slots GW1 bis GW4):</strong></li>\n<li>Die Abszisse stellt vier aufeinanderfolgende Sendezeitpunkte bzw. FlexRay-Kommunikationszyklen des Gateways dar (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>, <code>GW4</code>).</li>\n<li>Jeder farbige Block repräsentiert eine aus <code>PduPool_1</code> allozierte PDU (Consecutive Frame, CF), die an die adressierte Ziel-ECU gesendet wird.</li>\n<li><strong>Ablauf & PDU-Zuteilung pro Zyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus GW1:</strong> Maximaler Paralleldurchsatz. Aus <code>PduPool_1</code> werden gleichzeitig drei PDUs bereitgestellt: je eine für <code>ECU 1</code> (rot), <code>ECU 2</code> (blau) und <code>ECU 3</code> (grün).</li>\n<li><strong>Zyklus GW2:</strong> <code>Connection_ECU1</code> pausiert (FlowControl-Beschränkung aktiv). Es werden zwei PDUs versendet: an <code>ECU 2</code> und <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW3:</strong> <code>Connection_ECU2</code> pausiert ebenfalls (Separation-Cycle-Bedingung greift). Es wird nur eine PDU versendet: an <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW4:</strong> Erneut sendet nur <code>Connection_ECU3</code> (<code>Limited BW = False</code>) kontinuierlich in jedem Zyklus (1 PDU an <code>ECU 3</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Steuerungsmechanismus (ISO 10681-2 Flow Control):</strong></li>\n<li>Die Drosselung erfolgt über Empfänger-definierte Flow-Control-Parameter:</li>\n<li><code>SC</code> (<em>Separation Cycle</em>): Definiert die minimale Anzahl von FlexRay-Zyklen zwischen zwei aufeinanderfolgenden CFs.</li>\n<li><code>MNPC</code> (<em>Max Number of PDUs per Cycle</em>): Begrenzt die Frame-Anzahl pro Zyklus.</li>\n<li><code>BS</code> (<em>Block Size</em>): Bestimmt das Quittierungsintervall via Flow Control Frames (FC).</li>\n<li>Bei <code>Limited BW = True</code> wird das Senden gestreckt (Duty-Cycle-Reduktion), wodurch Verbindungen ohne Begrenzung (<code>Connection_ECU3</code>) freiwerdende Slot-Kapazitäten im PDU-Pool monopolisieren können.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>FrTp.epc</code> / ARXML):</strong></li>\n<li>Parameter <code>FrTpBandwidthLimitation</code> steuert, ob die Verbindungs-Zustandsmaschine des <code>FrTp</code> den PDU-Pool-Zugriff drosselt.</li>\n<li>Wenn mehrere Verbindungen auf einen gemeinsamen <code>FrTpPduPool</code> gemappt werden, muss über <code>Limited BW = True</code> sichergestellt werden, dass hochfrequente Bulk-Transfers (z. B. Flashen/UDS-Upload) unlimitierte Echtzeit-/Diagnoseverbindungen nicht aushungern (<em>Starvation Prevention</em>).</li>\n<li><strong>Scheduling in der <code>FrTp_MainFunction()</code>:</strong></li>\n<li>Der interne Zykluszähler für <code>Separation Cycle</code> (<code>SC</code>) wird im Kontext der zyklischen Main-Function dekrementiert.</li>\n<li>Erst wenn der Zähler abgelaufen ist und der <code>FrTpPduPool</code> freie PDU-Ressourcen meldet, ruft <code>FrTp</code> [<code>FrIf_Transmit()</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) auf.</li>\n<li><strong>Hardware-Puffer-Schutz (HW FIFO / Message Buffers):</strong></li>\n<li>Die Begrenzung verhindert RX-Pufferüberläufe ([<code>OVFLW</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)) auf Steuergeräten mit begrenzter Verarbeitungsgeschwindigkeit oder kleinen Empfangs-FIFOs, ohne dass separate, exklusive FlexRay-Slots für jedes Steuergerät reserviert werden müssen.</li>\n</ul>"}, {"id": "FIG-b6e6776a3854f636", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architektur- und Ressourcenallokationsdiagramm (logische Netzwerktopologie, Konfigurationsmatrix und zeitliches PDU-Scheduling-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Bandbreitenmanagements (<em>Bandwidth Control</em>) im FlexRay ISO Transport Layer ([<code>FrTp</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp), ISO 10681-2) bei Nutzung eines gemeinsamen PDU-Pools (<em>Shared PDU Pool</em>) über Flow-Control-Parameter.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Communication Services (zwischen [<code>PduR</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) und [<code>FrIf</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)). Löst Ressourcen- und Buslastkonflikte bei parallelen 1:n- bzw. n:1-Transportverbindungen eines Gateways (<code>GW ECU</code>) zu mehreren Steuergeräten (<code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>) über denselben PDU-Sende-Pool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Netzwerkknoten (Topology Layer):</strong></li>\n<li><code>GW</code> (<em>Gateway ECU</em>): Zentraler Sender segmentierter FlexRay-Transportnachrichten.</li>\n<li><code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>: Ziel-Steuergeräte (Empfänger) am gemeinsamen FlexRay-Kanal.</li>\n<li><strong>BSW-Konfigurationsentitäten (<code>FrTp</code>-Datenmodell):</strong></li>\n<li><code>Connection_ECU1</code>, <code>Connection_ECU2</code>, <code>Connection_ECU3</code> (<code>FrTpConnection</code>): Konfigurierte logische Punkt-zu-Punkt-Transportverbindungen zwischen <code>GW</code> und den jeweiligen Ziel-ECUs.</li>\n<li><code>PduPool_1</code> (<code>FrTpPduPool</code>): Gemeinsamer Pool vorkonfigurierter FlexRay-Sende-PDUs ([<code>FrIfTxPdu</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)), der von allen drei Verbindungen referenziert wird (<code>PduPoolRef = PduPool_1</code>).</li>\n<li><code>Limited BW</code> (<code>FrTpBandwidthLimitation</code>): Boolescher Verbindungsparameter zur Aktivierung der Ratenbegrenzung:</li>\n<li><code>Connection_ECU1</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU2</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU3</code>: <code>False</code> (keine statische/zusätzliche Bandbreitenbegrenzung)</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>$3:1$-Beziehung: Drei logische <code>FrTpConnection</code>-Instanzen teilen sich einen gemeinsamen physischen <code>FrTpPduPool</code> (<code>PduPool_1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitbasis (Transmissions-Slots GW1 bis GW4):</strong></li>\n<li>Die Abszisse stellt vier aufeinanderfolgende Sendezeitpunkte bzw. FlexRay-Kommunikationszyklen des Gateways dar (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>, <code>GW4</code>).</li>\n<li>Jeder farbige Block repräsentiert eine aus <code>PduPool_1</code> allozierte PDU (Consecutive Frame, CF), die an die adressierte Ziel-ECU gesendet wird.</li>\n<li><strong>Ablauf & PDU-Zuteilung pro Zyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus GW1:</strong> Maximaler Paralleldurchsatz. Aus <code>PduPool_1</code> werden gleichzeitig drei PDUs bereitgestellt: je eine für <code>ECU 1</code> (rot), <code>ECU 2</code> (blau) und <code>ECU 3</code> (grün).</li>\n<li><strong>Zyklus GW2:</strong> <code>Connection_ECU1</code> pausiert (FlowControl-Beschränkung aktiv). Es werden zwei PDUs versendet: an <code>ECU 2</code> und <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW3:</strong> <code>Connection_ECU2</code> pausiert ebenfalls (Separation-Cycle-Bedingung greift). Es wird nur eine PDU versendet: an <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW4:</strong> Erneut sendet nur <code>Connection_ECU3</code> (<code>Limited BW = False</code>) kontinuierlich in jedem Zyklus (1 PDU an <code>ECU 3</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Steuerungsmechanismus (ISO 10681-2 Flow Control):</strong></li>\n<li>Die Drosselung erfolgt über Empfänger-definierte Flow-Control-Parameter:</li>\n<li><code>SC</code> (<em>Separation Cycle</em>): Definiert die minimale Anzahl von FlexRay-Zyklen zwischen zwei aufeinanderfolgenden CFs.</li>\n<li><code>MNPC</code> (<em>Max Number of PDUs per Cycle</em>): Begrenzt die Frame-Anzahl pro Zyklus.</li>\n<li><code>BS</code> (<em>Block Size</em>): Bestimmt das Quittierungsintervall via Flow Control Frames (FC).</li>\n<li>Bei <code>Limited BW = True</code> wird das Senden gestreckt (Duty-Cycle-Reduktion), wodurch Verbindungen ohne Begrenzung (<code>Connection_ECU3</code>) freiwerdende Slot-Kapazitäten im PDU-Pool monopolisieren können.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>FrTp.epc</code> / ARXML):</strong></li>\n<li>Parameter <code>FrTpBandwidthLimitation</code> steuert, ob die Verbindungs-Zustandsmaschine des <code>FrTp</code> den PDU-Pool-Zugriff drosselt.</li>\n<li>Wenn mehrere Verbindungen auf einen gemeinsamen <code>FrTpPduPool</code> gemappt werden, muss über <code>Limited BW = True</code> sichergestellt werden, dass hochfrequente Bulk-Transfers (z. B. Flashen/UDS-Upload) unlimitierte Echtzeit-/Diagnoseverbindungen nicht aushungern (<em>Starvation Prevention</em>).</li>\n<li><strong>Scheduling in der <code>FrTp_MainFunction()</code>:</strong></li>\n<li>Der interne Zykluszähler für <code>Separation Cycle</code> (<code>SC</code>) wird im Kontext der zyklischen Main-Function dekrementiert.</li>\n<li>Erst wenn der Zähler abgelaufen ist und der <code>FrTpPduPool</code> freie PDU-Ressourcen meldet, ruft <code>FrTp</code> [<code>FrIf_Transmit()</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) auf.</li>\n<li><strong>Hardware-Puffer-Schutz (HW FIFO / Message Buffers):</strong></li>\n<li>Die Begrenzung verhindert RX-Pufferüberläufe ([<code>OVFLW</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)) auf Steuergeräten mit begrenzter Verarbeitungsgeschwindigkeit oder kleinen Empfangs-FIFOs, ohne dass separate, exklusive FlexRay-Slots für jedes Steuergerät reserviert werden müssen.</li>\n</ul>"}, {"id": "FIG-37863ca8e1c704aa", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architektur- und Ressourcenallokationsdiagramm (logische Netzwerktopologie, Konfigurationsmatrix und zeitliches PDU-Scheduling-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Bandbreitenmanagements (<em>Bandwidth Control</em>) im FlexRay ISO Transport Layer ([<code>FrTp</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp), ISO 10681-2) bei Nutzung eines gemeinsamen PDU-Pools (<em>Shared PDU Pool</em>) über Flow-Control-Parameter.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Communication Services (zwischen [<code>PduR</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) und [<code>FrIf</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)). Löst Ressourcen- und Buslastkonflikte bei parallelen 1:n- bzw. n:1-Transportverbindungen eines Gateways (<code>GW ECU</code>) zu mehreren Steuergeräten (<code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>) über denselben PDU-Sende-Pool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Netzwerkknoten (Topology Layer):</strong></li>\n<li><code>GW</code> (<em>Gateway ECU</em>): Zentraler Sender segmentierter FlexRay-Transportnachrichten.</li>\n<li><code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>: Ziel-Steuergeräte (Empfänger) am gemeinsamen FlexRay-Kanal.</li>\n<li><strong>BSW-Konfigurationsentitäten (<code>FrTp</code>-Datenmodell):</strong></li>\n<li><code>Connection_ECU1</code>, <code>Connection_ECU2</code>, <code>Connection_ECU3</code> (<code>FrTpConnection</code>): Konfigurierte logische Punkt-zu-Punkt-Transportverbindungen zwischen <code>GW</code> und den jeweiligen Ziel-ECUs.</li>\n<li><code>PduPool_1</code> (<code>FrTpPduPool</code>): Gemeinsamer Pool vorkonfigurierter FlexRay-Sende-PDUs ([<code>FrIfTxPdu</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)), der von allen drei Verbindungen referenziert wird (<code>PduPoolRef = PduPool_1</code>).</li>\n<li><code>Limited BW</code> (<code>FrTpBandwidthLimitation</code>): Boolescher Verbindungsparameter zur Aktivierung der Ratenbegrenzung:</li>\n<li><code>Connection_ECU1</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU2</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU3</code>: <code>False</code> (keine statische/zusätzliche Bandbreitenbegrenzung)</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>$3:1$-Beziehung: Drei logische <code>FrTpConnection</code>-Instanzen teilen sich einen gemeinsamen physischen <code>FrTpPduPool</code> (<code>PduPool_1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitbasis (Transmissions-Slots GW1 bis GW4):</strong></li>\n<li>Die Abszisse stellt vier aufeinanderfolgende Sendezeitpunkte bzw. FlexRay-Kommunikationszyklen des Gateways dar (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>, <code>GW4</code>).</li>\n<li>Jeder farbige Block repräsentiert eine aus <code>PduPool_1</code> allozierte PDU (Consecutive Frame, CF), die an die adressierte Ziel-ECU gesendet wird.</li>\n<li><strong>Ablauf & PDU-Zuteilung pro Zyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus GW1:</strong> Maximaler Paralleldurchsatz. Aus <code>PduPool_1</code> werden gleichzeitig drei PDUs bereitgestellt: je eine für <code>ECU 1</code> (rot), <code>ECU 2</code> (blau) und <code>ECU 3</code> (grün).</li>\n<li><strong>Zyklus GW2:</strong> <code>Connection_ECU1</code> pausiert (FlowControl-Beschränkung aktiv). Es werden zwei PDUs versendet: an <code>ECU 2</code> und <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW3:</strong> <code>Connection_ECU2</code> pausiert ebenfalls (Separation-Cycle-Bedingung greift). Es wird nur eine PDU versendet: an <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW4:</strong> Erneut sendet nur <code>Connection_ECU3</code> (<code>Limited BW = False</code>) kontinuierlich in jedem Zyklus (1 PDU an <code>ECU 3</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Steuerungsmechanismus (ISO 10681-2 Flow Control):</strong></li>\n<li>Die Drosselung erfolgt über Empfänger-definierte Flow-Control-Parameter:</li>\n<li><code>SC</code> (<em>Separation Cycle</em>): Definiert die minimale Anzahl von FlexRay-Zyklen zwischen zwei aufeinanderfolgenden CFs.</li>\n<li><code>MNPC</code> (<em>Max Number of PDUs per Cycle</em>): Begrenzt die Frame-Anzahl pro Zyklus.</li>\n<li><code>BS</code> (<em>Block Size</em>): Bestimmt das Quittierungsintervall via Flow Control Frames (FC).</li>\n<li>Bei <code>Limited BW = True</code> wird das Senden gestreckt (Duty-Cycle-Reduktion), wodurch Verbindungen ohne Begrenzung (<code>Connection_ECU3</code>) freiwerdende Slot-Kapazitäten im PDU-Pool monopolisieren können.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>FrTp.epc</code> / ARXML):</strong></li>\n<li>Parameter <code>FrTpBandwidthLimitation</code> steuert, ob die Verbindungs-Zustandsmaschine des <code>FrTp</code> den PDU-Pool-Zugriff drosselt.</li>\n<li>Wenn mehrere Verbindungen auf einen gemeinsamen <code>FrTpPduPool</code> gemappt werden, muss über <code>Limited BW = True</code> sichergestellt werden, dass hochfrequente Bulk-Transfers (z. B. Flashen/UDS-Upload) unlimitierte Echtzeit-/Diagnoseverbindungen nicht aushungern (<em>Starvation Prevention</em>).</li>\n<li><strong>Scheduling in der <code>FrTp_MainFunction()</code>:</strong></li>\n<li>Der interne Zykluszähler für <code>Separation Cycle</code> (<code>SC</code>) wird im Kontext der zyklischen Main-Function dekrementiert.</li>\n<li>Erst wenn der Zähler abgelaufen ist und der <code>FrTpPduPool</code> freie PDU-Ressourcen meldet, ruft <code>FrTp</code> [<code>FrIf_Transmit()</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) auf.</li>\n<li><strong>Hardware-Puffer-Schutz (HW FIFO / Message Buffers):</strong></li>\n<li>Die Begrenzung verhindert RX-Pufferüberläufe ([<code>OVFLW</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)) auf Steuergeräten mit begrenzter Verarbeitungsgeschwindigkeit oder kleinen Empfangs-FIFOs, ohne dass separate, exklusive FlexRay-Slots für jedes Steuergerät reserviert werden müssen.</li>\n</ul>"}, {"id": "FIG-bdf58dfec6c9eb77", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architektur- und Ressourcenallokationsdiagramm (logische Netzwerktopologie, Konfigurationsmatrix und zeitliches PDU-Scheduling-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Bandbreitenmanagements (<em>Bandwidth Control</em>) im FlexRay ISO Transport Layer ([<code>FrTp</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp), ISO 10681-2) bei Nutzung eines gemeinsamen PDU-Pools (<em>Shared PDU Pool</em>) über Flow-Control-Parameter.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Communication Services (zwischen [<code>PduR</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) und [<code>FrIf</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)). Löst Ressourcen- und Buslastkonflikte bei parallelen 1:n- bzw. n:1-Transportverbindungen eines Gateways (<code>GW ECU</code>) zu mehreren Steuergeräten (<code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>) über denselben PDU-Sende-Pool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Netzwerkknoten & Rollen (Topology Layer):</strong></li>\n<li><code>GW</code> (<em>Gateway ECU</em>): Zentraler Sender segmentierter FlexRay-Transportnachrichten, explizit als <code>Sender</code> ausgewiesen.</li>\n<li><code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>: Ziel-Steuergeräte am gemeinsamen FlexRay-Kanal, explizit als <code>Receiver</code> ausgewiesen.</li>\n<li><strong>Durchflussbegrenzungen (Flow Control Limits):</strong></li>\n<li><code>ECU 1</code>: <code>Limit: MPPC = 1</code> (Max Packets Per Cycle auf maximal 1 PDU pro FlexRay-Zyklus begrenzt).</li>\n<li><code>ECU 2</code>: <code>Limit: MPPC = 2</code> (Max Packets Per Cycle auf maximal 2 PDUs pro FlexRay-Zyklus begrenzt).</li>\n<li><code>ECU 3</code>: <code>Limit: MPPC = 4</code> (Max Packets Per Cycle auf bis zu 4 PDUs pro FlexRay-Zyklus ausgelegt).</li>\n<li><strong>BSW-Konfigurationsentitäten (<code>FrTp</code>-Datenmodell):</strong></li>\n<li><code>Connection_ECU1</code>, <code>Connection_ECU2</code>, <code>Connection_ECU3</code> (<code>FrTpConnection</code>): Konfigurierte logische Punkt-zu-Punkt-Transportverbindungen zwischen <code>GW</code> und den jeweiligen Ziel-ECUs.</li>\n<li><code>PduPool_1</code> (<code>FrTpPduPool</code>): Gemeinsamer Pool vorkonfigurierter FlexRay-Sende-PDUs ([<code>FrIfTxPdu</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/bd/bdf58dfec6c9eb777d09da3e3bc8e749bb20666b45c07794f0f9baf1528dfc12.webp)), der von allen drei Verbindungen referenziert wird (<code>PduPoolRef = PduPool_1</code>).</li>\n<li><code>Limited BW</code> (<code>FrTpBandwidthLimitation</code>): Boolescher Verbindungsparameter zur Aktivierung der Ratenbegrenzung:</li>\n<li><code>Connection_ECU1</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU2</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU3</code>: <code>False</code> (keine statische/zusätzliche Bandbreitenbegrenzung)</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>$3:1$-Beziehung: Drei logische <code>FrTpConnection</code>-Instanzen teilen sich einen gemeinsamen physischen <code>FrTpPduPool</code> (<code>PduPool_1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitbasis (Transmissions-Slots GW1 bis GW4):</strong></li>\n<li>Die Abszisse stellt vier aufeinanderfolgende Sendezeitpunkte bzw. FlexRay-Kommunikationszyklen des Gateways dar (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>, <code>GW4</code>).</li>\n<li>Jeder farbige Block repräsentiert eine aus <code>PduPool_1</code> allozierte PDU (Consecutive Frame, CF), die an die adressierte Ziel-ECU gesendet wird.</li>\n<li><strong>Ablauf & PDU-Zuteilung pro Zyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus GW1:</strong> Maximaler Paralleldurchsatz. Aus <code>PduPool_1</code> werden gleichzeitig drei PDUs bereitgestellt: je eine für <code>ECU 1</code> (rot), <code>ECU 2</code> (blau) und <code>ECU 3</code> (grün).</li>\n<li><strong>Zyklus GW2:</strong> <code>Connection_ECU1</code> pausiert (FlowControl-Beschränkung aktiv). Es werden zwei PDUs versendet: an <code>ECU 2</code> und <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW3:</strong> <code>Connection_ECU2</code> pausiert ebenfalls (Separation-Cycle-Bedingung greift). Es wird nur eine PDU versendet: an <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW4:</strong> Erneut sendet nur <code>Connection_ECU3</code> (<code>Limited BW = False</code>) kontinuierlich in jedem Zyklus (1 PDU an <code>ECU 3</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Steuerungsmechanismus (ISO 10681-2 Flow Control):</strong></li>\n<li>Die Drosselung erfolgt über Empfänger-definierte Flow-Control-Parameter:</li>\n<li><code>SC</code> (<em>Separation Cycle</em>): Definiert die minimale Anzahl von FlexRay-Zyklen zwischen zwei aufeinanderfolgenden CFs.</li>\n<li><code>MNPC</code> (<em>Max Number of PDUs per Cycle</em>): Begrenzt die Frame-Anzahl pro Zyklus.</li>\n<li><code>BS</code> (<em>Block Size</em>): Bestimmt das Quittierungsintervall via Flow Control Frames (FC).</li>\n<li>Bei <code>Limited BW = True</code> wird das Senden gestreckt (Duty-Cycle-Reduktion), wodurch Verbindungen ohne Begrenzung (<code>Connection_ECU3</code>) freiwerdende Slot-Kapazitäten im PDU-Pool monopolisieren können.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>FrTp.epc</code> / ARXML):</strong></li>\n<li>Parameter <code>FrTpBandwidthLimitation</code> steuert, ob die Verbindungs-Zustandsmaschine des <code>FrTp</code> den PDU-Pool-Zugriff drosselt.</li>\n<li>Wenn mehrere Verbindungen auf einen gemeinsamen <code>FrTpPduPool</code> gemappt werden, muss über <code>Limited BW = True</code> sichergestellt werden, dass hochfrequente Bulk-Transfers (z. B. Flashen/UDS-Upload) unlimitierte Echtzeit-/Diagnoseverbindungen nicht aushungern (<em>Starvation Prevention</em>).</li>\n<li><strong>Scheduling in der <code>FrTp_MainFunction()</code>:</strong></li>\n<li>Der interne Zykluszähler für <code>Separation Cycle</code> (<code>SC</code>) wird im Kontext der zyklischen Main-Function dekrementiert.</li>\n<li>Erst wenn der Zähler abgelaufen ist und der <code>FrTpPduPool</code> freie PDU-Ressourcen meldet, ruft <code>FrTp</code> [<code>FrIf_Transmit()</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) auf.</li>\n<li><strong>Hardware-Puffer-Schutz (HW FIFO / Message Buffers):</strong></li>\n<li>Die Begrenzung verhindert RX-Pufferüberläufe ([<code>OVFLW</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)) auf Steuergeräten mit begrenzter Verarbeitungsgeschwindigkeit oder kleinen Empfangs-FIFOs, ohne dass separate, exklusive FlexRay-Slots für jedes Steuergerät reserviert werden müssen.</li>\n</ul>"}, {"id": "FIG-e6ecec3a0b0d9ffa", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architektur- und Ressourcenallokationsdiagramm (logische Netzwerktopologie, Konfigurationsmatrix und zeitliches PDU-Scheduling-Schema).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Bandbreitenmanagements (<em>Bandwidth Control</em>) im FlexRay ISO Transport Layer ([<code>FrTp</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp), ISO 10681-2) bei Nutzung eines gemeinsamen PDU-Pools (<em>Shared PDU Pool</em>) über Flow-Control-Parameter.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Communication Services (zwischen [<code>PduR</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) und [<code>FrIf</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)). Löst Ressourcen- und Buslastkonflikte bei parallelen 1:n- bzw. n:1-Transportverbindungen eines Gateways (<code>GW ECU</code>) zu mehreren Steuergeräten (<code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>) über denselben PDU-Sende-Pool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Netzwerkknoten & Rollen (Topology Layer):</strong></li>\n<li><code>GW</code> (<em>Gateway ECU</em>): Zentraler Sender segmentierter FlexRay-Transportnachrichten, explizit als <code>Sender</code> ausgewiesen.</li>\n<li><code>ECU 1</code>, <code>ECU 2</code>, <code>ECU 3</code>: Ziel-Steuergeräte am gemeinsamen FlexRay-Kanal, explizit als <code>Receiver</code> ausgewiesen.</li>\n<li><strong>Durchflussbegrenzungen (Flow Control Limits):</strong></li>\n<li><code>ECU 1</code>: <code>Limit: MPPC = 1</code> (Max Packets Per Cycle auf maximal 1 PDU pro FlexRay-Zyklus begrenzt).</li>\n<li><code>ECU 2</code>: <code>Limit: MPPC = 2</code> (Max Packets Per Cycle auf maximal 2 PDUs pro FlexRay-Zyklus begrenzt).</li>\n<li><code>ECU 3</code>: <code>Limit: MPPC = 4</code> (Max Packets Per Cycle auf bis zu 4 PDUs pro FlexRay-Zyklus ausgelegt).</li>\n<li><strong>BSW-Konfigurationsentitäten (<code>FrTp</code>-Datenmodell):</strong></li>\n<li><code>Connection_ECU1</code>, <code>Connection_ECU2</code>, <code>Connection_ECU3</code> (<code>FrTpConnection</code>): Konfigurierte logische Punkt-zu-Punkt-Transportverbindungen zwischen <code>GW</code> und den jeweiligen Ziel-ECUs.</li>\n<li><code>PduPool_1</code> (<code>FrTpPduPool</code>): Gemeinsamer Pool vorkonfigurierter FlexRay-Sende-PDUs ([<code>FrIfTxPdu</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/bd/bdf58dfec6c9eb777d09da3e3bc8e749bb20666b45c07794f0f9baf1528dfc12.webp)), der von allen drei Verbindungen referenziert wird (<code>PduPoolRef = PduPool_1</code>).</li>\n<li><code>Limited BW</code> (<code>FrTpBandwidthLimitation</code>): Boolescher Verbindungsparameter zur Aktivierung der Ratenbegrenzung:</li>\n<li><code>Connection_ECU1</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU2</code>: <code>True</code> (Bandbreite gedrosselt)</li>\n<li><code>Connection_ECU3</code>: <code>False</code> (keine statische/zusätzliche Bandbreitenbegrenzung)</li>\n<li><strong>Kardinalitäten:</strong></li>\n<li>$3:1$-Beziehung: Drei logische <code>FrTpConnection</code>-Instanzen teilen sich einen gemeinsamen physischen <code>FrTpPduPool</code> (<code>PduPool_1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitbasis (Transmissions-Slots GW1 bis GW4):</strong></li>\n<li>Die Abszisse stellt vier aufeinanderfolgende Sendezeitpunkte bzw. FlexRay-Kommunikationszyklen des Gateways dar (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>, <code>GW4</code>).</li>\n<li>Jeder farbige Block repräsentiert eine aus <code>PduPool_1</code> allozierte PDU (Consecutive Frame, CF), die an die adressierte Ziel-ECU gesendet wird.</li>\n<li><strong>Ablauf & PDU-Zuteilung pro Zyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus GW1:</strong> Maximaler Paralleldurchsatz. Aus <code>PduPool_1</code> werden gleichzeitig drei PDUs bereitgestellt: je eine für <code>ECU 1</code> (rot), <code>ECU 2</code> (blau) und <code>ECU 3</code> (grün).</li>\n<li><strong>Zyklus GW2:</strong> <code>Connection_ECU1</code> pausiert (FlowControl-Beschränkung aktiv). Es werden zwei PDUs versendet: an <code>ECU 2</code> und <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW3:</strong> <code>Connection_ECU2</code> pausiert ebenfalls (Separation-Cycle-Bedingung greift). Es wird nur eine PDU versendet: an <code>ECU 3</code>.</li>\n<li><strong>Zyklus GW4:</strong> Erneut sendet nur <code>Connection_ECU3</code> (<code>Limited BW = False</code>) kontinuierlich in jedem Zyklus (1 PDU an <code>ECU 3</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Steuerungsmechanismus (ISO 10681-2 Flow Control):</strong></li>\n<li>Die Drosselung erfolgt über Empfänger-definierte Flow-Control-Parameter:</li>\n<li><code>SC</code> (<em>Separation Cycle</em>): Definiert die minimale Anzahl von FlexRay-Zyklen zwischen zwei aufeinanderfolgenden CFs.</li>\n<li><code>MNPC</code> (<em>Max Number of PDUs per Cycle</em>): Begrenzt die Frame-Anzahl pro Zyklus.</li>\n<li><code>BS</code> (<em>Block Size</em>): Bestimmt das Quittierungsintervall via Flow Control Frames (FC).</li>\n<li>Bei <code>Limited BW = True</code> wird das Senden gestreckt (Duty-Cycle-Reduktion), wodurch Verbindungen ohne Begrenzung (<code>Connection_ECU3</code>) freiwerdende Slot-Kapazitäten im PDU-Pool monopolisieren können.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>FrTp.epc</code> / ARXML):</strong></li>\n<li>Parameter <code>FrTpBandwidthLimitation</code> steuert, ob die Verbindungs-Zustandsmaschine des <code>FrTp</code> den PDU-Pool-Zugriff drosselt.</li>\n<li>Wenn mehrere Verbindungen auf einen gemeinsamen <code>FrTpPduPool</code> gemappt werden, muss über <code>Limited BW = True</code> sichergestellt werden, dass hochfrequente Bulk-Transfers (z. B. Flashen/UDS-Upload) unlimitierte Echtzeit-/Diagnoseverbindungen nicht aushungern (<em>Starvation Prevention</em>).</li>\n<li><strong>Scheduling in der <code>FrTp_MainFunction()</code>:</strong></li>\n<li>Der interne Zykluszähler für <code>Separation Cycle</code> (<code>SC</code>) wird im Kontext der zyklischen Main-Function dekrementiert.</li>\n<li>Erst wenn der Zähler abgelaufen ist und der <code>FrTpPduPool</code> freie PDU-Ressourcen meldet, ruft <code>FrTp</code> [<code>FrIf_Transmit()</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp) auf.</li>\n<li><strong>Hardware-Puffer-Schutz (HW FIFO / Message Buffers):</strong></li>\n<li>Die Begrenzung verhindert RX-Pufferüberläufe ([<code>OVFLW</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/02/02bda491f2322b655f5c355a10d5d49f220610b2d6e9579db4bb91922e519520.webp)) auf Steuergeräten mit begrenzter Verarbeitungsgeschwindigkeit oder kleinen Empfangs-FIFOs, ohne dass separate, exklusive FlexRay-Slots für jedes Steuergerät reserviert werden müssen.</li>\n</ul>"}], "trans": [{"from": "FIG-02bda491f2322b65", "to": "FIG-b44ac6e3ddf2438d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b44ac6e3ddf2438d", "to": "FIG-b6e6776a3854f636", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b6e6776a3854f636", "to": "FIG-37863ca8e1c704aa", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-37863ca8e1c704aa", "to": "FIG-bdf58dfec6c9eb77", "fr": "R19-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Knoten GW: Rollenbezeichnung „Sender“ über dem Block ergänzt.</li>\n<li>Knoten ECU 1: Rollenbezeichnung „Receiver“ sowie Parameterbeschränkung „Limit: MPPC = 1“ ergänzt.</li>\n<li>Knoten ECU 2: Rollenbezeichnung „Receiver“ sowie Parameterbeschränkung „Limit: MPPC = 2“ ergänzt.</li>\n<li>Knoten ECU 3: Rollenbezeichnung „Receiver“ sowie Parameterbeschränkung „Limit: MPPC = 4“ ergänzt.</li>\n<li>Zeitachse: Vollständige Beschriftung der Kommunikationszyklen (GW1, GW2, GW3, GW4) unterhalb der Zeitachse wiederhergestellt.</li>\n</ul>"}, {"from": "FIG-bdf58dfec6c9eb77", "to": "FIG-e6ecec3a0b0d9ffa", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
